"""Ask Claude node generated by aotn_node_helper."""

from typing import Any, ClassVar, Dict, List, Optional

from ...node_base import Node, NodeContext
from ...node_category import NodeCategory


class AskClaudeNode(Node):
    """Ask one hosted question with optional Context; returns one answer."""

    node_type: ClassVar[str] = 'ask_claude_node'
    display_name: ClassVar[str] = 'Ask Claude'
    default_alias: ClassVar[str] = 'Ask Claude'
    description: ClassVar[str] = 'Ask one hosted question with optional Context; returns one answer'
    category: ClassVar[str] = NodeCategory.AI
    primary_family: ClassVar[str] = 'Complex'
    tags: ClassVar[List[str]] = ['question', 'JSON', 'Claude']
    icon_name: ClassVar[str] = 'message-circle'
    color_hint: ClassVar[str] = 'violet'
    group: ClassVar[Optional[str]] = None
    selector_section: ClassVar[Optional[str]] = 'AI'
    input_ports: ClassVar[List[str]] = ['input', 'context']
    output_ports: ClassVar[List[str]] = ['default', 'details']
    input_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'input': {'name': 'Question', 'description': '', 'data_type': 'string', 'required': True, 'sources': ['upstream', 'vault', 'configured']}, 'context': {'name': 'Context', 'description': '', 'data_type': 'string', 'required': False, 'sources': ['upstream', 'vault', 'configured']}}
    output_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'default': {'name': 'Answer', 'description': 'The final answer as text; JSON mode still returns text', 'data_type': 'string', 'required': True, 'to': ['downstream', 'vault'], 'pass_through': True}, 'details': {'name': 'Run details', 'description': 'Model, tokens, stop reason, wall time and cost estimate; no prompt or credentials', 'data_type': 'var', 'required': False, 'to': ['vault']}}
    default_config: ClassVar[Dict[str, Any]] = {'input_source': 'Configured', 'input_vault_key': '', 'input': '', 'context_source': 'Configured', 'context_vault_key': '', 'context': '', 'model': 'Options default', 'timeout': 120, 'reply_json': False, 'max_tokens': 2048, 'context_limit': '', 'effort': 'low', 'transient_output': True, 'dead_drop_passthrough': False, 'transient_outputs': [], 'vault_write': False, 'vault_write_key': '', 'vault_write_description': '', 'details_vault_write': False, 'details_vault_key': '', 'details_vault_description': ''}
    config_schema: ClassVar[Dict[str, Dict[str, Any]]] = {'input_source': {'type': 'select', 'label': 'Input source', 'options': ['Upstream payload', 'Vault', 'Configured'], 'tab': 'Source', 'section': 'Required Inputs'}, 'input_vault_key': {'type': 'string', 'label': 'Input Vault key', 'required': False, 'tab': 'Source', 'section': 'Required Inputs', 'vault_type': 'string', 'visible_when': {'input_source': 'Vault'}}, 'input': {'type': 'multiline', 'label': 'Question', 'preview': True, 'height': 5, 'description': 'One question, no tools or history. Optional Context is data, not instructions.', 'tab': 'Parameters', 'visible_when': {'input_source': 'Configured'}}, 'context_source': {'type': 'select', 'label': 'Context source', 'options': ['Upstream payload', 'Vault', 'Configured'], 'tab': 'Source', 'section': 'Optional Inputs'}, 'context_vault_key': {'type': 'string', 'label': 'Context Vault key', 'required': False, 'tab': 'Source', 'section': 'Optional Inputs', 'vault_type': 'string', 'visible_when': {'context_source': 'Vault'}}, 'context': {'type': 'multiline', 'label': 'Context', 'preview': True, 'height': 5, 'description': 'Optional facts. Uses Context limit; total question limit is that limit + 12,000.', 'tab': 'Parameters', 'visible_when': {'context_source': 'Configured'}}, 'model': {'type': 'string', 'label': 'Model override', 'options': ['Options default', 'claude-haiku-5-5', 'claude-sonnet-5-5', 'claude-opus-5-5'], 'description': 'Options default uses Claude model in Options.', 'tab': 'Parameters'}, 'timeout': {'type': 'integer', 'label': 'Stop after (seconds)', 'min': 10, 'max': 600, 'description': 'Total time including SDK retries. Stops waiting at this limit.', 'tab': 'Parameters'}, 'reply_json': {'type': 'boolean', 'label': 'Reply as JSON', 'description': 'Returns JSON text. Use Check reply for expected fields.', 'tab': 'Parameters'}, 'max_tokens': {'type': 'integer', 'label': 'Max output tokens', 'min': 1, 'max': 8192, 'tab': 'Parameters'}, 'context_limit': {'type': 'integer', 'allow_blank': True, 'label': 'Context limit', 'min': 1000, 'max': 200000, 'placeholder': 'Blank = Options default', 'description': 'Characters, 1,000–200,000. Blank uses Claude context limit in Options. No truncation.', 'tab': 'Parameters'}, 'effort': {'type': 'string', 'label': 'Effort', 'options': ['low', 'medium', 'high'], 'tab': 'Parameters'}}
    ui_hints: ClassVar[Dict[str, Any]] = {}
    error_definitions: ClassVar[List[Dict[str, Any]]] = [{'code': 'missing_key', 'description': 'Add ANTHROPIC_API_KEY in Options → Secrets.', 'retryable': False}, {'code': 'settings_invalid', 'description': 'Check Claude model and context limit in Options.', 'retryable': False}, {'code': 'invalid_config', 'description': 'Check the question, Context, limits and Vault outputs.', 'retryable': False}, {'code': 'auth_error', 'description': 'The API rejected the key; check ANTHROPIC_API_KEY in Secrets.', 'retryable': False}, {'code': 'rate_limited', 'description': 'The API rate limit was reached; wait before running again.', 'retryable': False}, {'code': 'overloaded', 'description': 'The API is overloaded; try later.', 'retryable': False}, {'code': 'network_error', 'description': 'Could not reach the API; check the connection.', 'retryable': False}, {'code': 'timed_out', 'description': 'Stopped waiting at the time limit.', 'retryable': False}, {'code': 'api_error', 'description': 'The API could not finish the request.', 'retryable': False}, {'code': 'refusal', 'description': 'The API declined the request.', 'retryable': False}, {'code': 'incomplete_reply', 'description': 'The reply was cut off or did not finish.', 'retryable': False}, {'code': 'invalid_response', 'description': 'The API did not return a valid answer.', 'retryable': False}, {'code': 'response_too_large', 'description': 'The answer is too large.', 'retryable': False}, {'code': 'context_too_long', 'description': 'Context exceeds its character limit; shorten it or raise the limit.', 'retryable': False}, {'code': 'text_too_long', 'description': 'The assembled question exceeds Context limit + 12,000 characters.', 'retryable': False}]

    default_config['context_source'] = 'Not used'
    config_schema['context_source']['options'].insert(0, 'Not used')

    async def execute(self, context: NodeContext) -> None:
        from ...integrations import claude
        from ...node_errors import NodeError
        try:
            model, question = claude.prepare(self.config, context)
            key = context.get_secret('ANTHROPIC_API_KEY')
            if not isinstance(key, str) or not key.strip():
                raise claude.failure('missing_key')
            manager = context.secrets_manager
            known = (key, *(v for name in manager.list_keys()
                            if (v := manager.get_secret(name))))
            result = await claude.ask(key=key, known=known, model=model, question=question,
                timeout=self.config['timeout'], reply_json=self.config['reply_json'],
                effort=self.config['effort'], max_tokens=self.config['max_tokens'])
        except NodeError as exc:
            context.signal_error(exc)
            return
        if self.config['details_vault_write']:
            context.memory_bank.store_persistent(self.config['details_vault_key'].strip(), result.details, type_tag='var')
        if self.config['vault_write']:
            context.memory_bank.store_persistent(self.config['vault_write_key'].strip(), result.text, type_tag='string')
        forwarding = self.config['dead_drop_passthrough']
        payload = context.inputs.get('input') if forwarding else result.text
        context.signal_done({'data': {'default': payload}
                             if forwarding or self.config['transient_output'] else {}})
